      hu: ["A kereskedelmi célú termelés hivatalosan 1978-ban vette kezdetét.", "A Syncrude eddig több mint 3 milliárd hordó nyersolajat állított elő.", "A Mildred Lake létesítmény területe megközelítőleg 40 000 hektár.", "A vállalat évente több mint 100 millió dollárt költ kutatás-fejlesztésre.", "Körülbelül 5000 állandó alkalmazott dolgozik közvetlenül a helyszínen.", "A bitument legfeljebb 60 méteres mélységig terjedő rétegekből nyerik ki."],
