      fr: ["Capacité annuelle prévue : 10 millions de tonnes de GNL", "Lieu : Douglas Channel, Kitimat", "Investisseurs : Chevron et Woodside Petroleum", "Gazoduc : depuis le bassin de Montney", "Début de la construction : 2011", "Date d'achèvement prévue : indéterminée"],
