      pt: ["Capacidade instalada no Canadá: 8.000 MW", "Barragens principais: Mica, Revelstoke, Keenleyside", "Queda do rio Columbia: mais de 800 m", "Início da construção: década de 1960", "Tratado: Columbia River Treaty", "Exportação para os EUA: aprox. 3.000 MW"],
      fr: ["Puissance installée au Canada : 8 000 MW", "Principaux barrages : Mica, Revelstoke, Keenleyside", "Hauteur de chute du fleuve Columbia : plus de 800 m", "Début de la construction : années 1960", "Traité : Columbia River Treaty", "Exportation vers les États-Unis : env. 3 000 MW"],
