      ro: ["Peste 60 de instalații industriale în regiune", "Produce 40% din produsele chimice canadiene", "Primul puț de petrol comercial (1858)", "Hub pentru conducta Enbridge Line 5", "Producție majoră de cauciuc sintetic", "Locație majoră de export pentru polimeri"],
      en: ["Over 60 industrial facilities in the region", "Produces 40% of Canada's chemical products", "First commercial oil well in NA (1858)", "Hub for the Enbridge Line 5 pipeline", "Major production of synthetic rubber", "Key export location for polymers"],
