      ro: ["Principalul port de export pentru cartofii din Insula Prințului Edward.", "Primește anual peste 70 de nave de croazieră în timpul sezonului.", "Dispune de o adâncime a apei de până la 10 metri la cheiuri.", "Este operat de Autoritatea Portuară Charlottetown, înființată în 1999.", "Punct strategic de aprovizionare cu combustibil pentru întreaga insulă.", "Capabil să primească nave comerciale cu o lungime de până la 200 metri."],
      en: ["Primary export gateway for Prince Edward Island's potato industry.", "Welcomes over 70 large cruise ships annually during the tourist season.", "Features a water depth of up to 10 meters at the main berths.", "Managed by the independent Charlottetown Harbour Authority since 1999.", "Acts as a strategic distribution point for petroleum products on the island.", "Capable of accommodating commercial vessels up to 200 meters in length."],
