      pt: ["Profundidade da água: até 10 m", "Comprimento máximo do navio: 200 m", "Número de navios de cruzeiro por temporada: mais de 70", "Carga principal: batatas, cereais, frutos do mar", "Gestão: Charlottetown Harbour Authority", "Conexões de balsa: para a Nova Escócia e Îles de la Madeleine"],
      fr: ["Profondeur d'eau : jusqu'à 10 m", "Longueur maximale des navires : 200 m", "Nombre de navires de croisière par saison : plus de 70", "Cargaison principale : pommes de terre, céréales, fruits de mer", "Gestion : Administration portuaire de Charlottetown", "Liaisons par traversier : vers la Nouvelle-Écosse et les îles de la Madeleine"],
